// <free_field_name>颜色选择器</free_field_name>
// <file_name>ColorPicker_v1.jsx</file_name>
function ColorPicker({ value, onChange, env }) {
  const isDisabled = env?.isDisabled || false;

  const handleColorChange = (e) => {
    const selectedColor = e.target.value;
    onChange(selectedColor);
  };

  return (
    <input
      type="color"
      className={`w-[36px] h-[36px] border rounded-md ${isDisabled ? 'cursor-not-allowed opacity-50' : ''}`}
      value={value || '#000000'} // 默认值为黑色
      onChange={handleColorChange}
      disabled={isDisabled}
    />
  );
}

// <free_field_name>JSON编辑器</free_field_name>
// <file_name>JsonEditor_v1.jsx</file_name>
function JsonEditor({ value, onChange }) {
  const [inputValue, setInputValue] = useState(value);
  const [isValidJson, setIsValidJson] = useState(true);

  useEffect(() => {
    setInputValue(value);
  }, [value]);

  const handleChange = (e) => {
    const newValue = e.target.value;
    setInputValue(newValue);

    try {
      JSON.parse(newValue);
      setIsValidJson(true);
      onChange(newValue);
    } catch (error) {
      setIsValidJson(false);
    }
  };

  return (
    <div>
      <textarea
        className={`w-full h-[100px] p-2 border rounded-md border-gray-300 ${isValidJson ? '' : 'border-red-500'}`}
        value={inputValue}
        onChange={handleChange}
        placeholder="请输入 JSON 对象"
      />
      {!isValidJson && <p className="text-red-500 text-sm">请输入有效的 JSON 格式</p>}
    </div>
  );
}

